      choices: ["[レコードの詳細]コンポーネントから項目を削除する。","フィルタ付きの[タブ]コンポーネントを増やす。","ページから余分なコンポーネントを削除する。","コンポーネントで[コンポーネントの表示を設定]を設定する。"],
