      question: "管理者は、取引先の簡単な項目更新を自動化するよう依頼されました。サポートエージェントが取引先のステータス項目を「監査済み」に変更した場合、取引先の監査日項目を今日の日付で自動的に更新してほしいとのことです。この自動化を完了するために、管理者はどのツールを使用すべきでしょうか。",
      choices: ["フロービルダー","承認プロセス","数式項目","入力規則"],
      answers: [0],
      explanation: `フロービルダーを使用すると、条件に基づいてレコードを自動的に更新することができます。この場合、取引先のステータスが「監査済み」に変更されたときに、監査日項目を今日の日付で自動更新するためのフローを作成できます。フロービルダーは、Salesforceの自動化ツールとして強力で柔軟性があります。
        ※ 承認プロセスは、レコードが特定の基準を満たしたときに、一連の承認手順を要求するために使用されます。取引先のステータスが「監査済み」に変更されたときに自動的に監査日項目を更新するという要件には適していません。
        ※ 数式項目は、レコードの他の項目の値に基づいて計算された値を表示するために使用されます。数式項目は読み取り専用であり、値を動的に更新することはできません。この場合、監査日項目を今日の日付で自動的に更新するためには適していません。
        ※ 入力規則は、レコードの保存時に特定の条件が満たされることを強制するために使用されます。入力規則は値の設定や更新を行うものではなく、特定の条件が満たされない場合にエラーメッセージを表示して保存を防ぐためのものです。`
