      choices: ["顧客のメールアドレスが見つからないため、メールは送信されない。","メールは、30日間のリマインダー基準で送信される。","レコードが条件を満たさなくなったため、メールは送信されない。","メールは、条件を満たすまでジョブキューにロックされる。"],
